{
  "pytorch": {
    "description": "Applies a 1D adaptive average pooling.",
    "definition_type": "operator",
    "math_symbol": "Sum(\n  Piecewise(\n    (X[n, c, k], \n     (k >= floor(w * Dim(X, 2) / W_out)) & \n     (k < ceiling((w + 1) * Dim(X, 2) / W_out))),\n    (0, True)\n  ),\n  (k, 0, Dim(X, 2) - 1)\n) / (ceiling((w + 1) * Dim(X, 2) / W_out) - floor(w * Dim(X, 2) / W_out))\n",
    "param_map": {
      "output_size": "W_out"
    },
    "output_shape": [
      "Dim(X, 0)",
      "Dim(X, 1)",
      "W_out"
    ],
    "mechanisms": [
      {
        "description": "Valid Output Size",
        "check": "W_out > 0"
      }
    ]
  },
  "paddle": {
    "description": "Adaptive 1D average pooling. Calculates dynamic window: [start, end).",
    "definition_type": "operator",
    "math_symbol": "Y[n, c, i] == Sum(\n  X[n, c, l],\n  (l, floor(i * Dim(X, 2) / output_size), ceiling((i + 1) * Dim(X, 2) / output_size) - 1)\n) / (ceiling((i + 1) * Dim(X, 2) / output_size) - floor(i * Dim(X, 2) / output_size))\n",
    "param_map": {
      "output_size": "output_size"
    },
    "output_shape": [
      "Dim(X, 0)",
      "Dim(X, 1)",
      "output_size"
    ],
    "mechanisms": [
      {
        "description": "Output Dimension Constraint",
        "check": "Eq(Dim(Y, 2), output_size)"
      },
      {
        "description": "Valid Output Size",
        "check": "Gt(output_size, 0)"
      }
    ]
  }
}

{
  "pytorch": {
    "description": "Applies a 2D adaptive average pooling.",
    "definition_type": "operator",
    "math_symbol": "Sum(\n  Sum(\n    Piecewise(\n      (X[n, c, kh, kw],\n       (kh >= floor(h * Dim(X, 2) / H_out)) & \n       (kh < ceiling((h + 1) * Dim(X, 2) / H_out)) &\n       (kw >= floor(w * Dim(X, 3) / W_out)) & \n       (kw < ceiling((w + 1) * Dim(X, 3) / W_out))),\n      (0, True)\n    ),\n    (kw, 0, Dim(X, 3) - 1)\n  ),\n  (kh, 0, Dim(X, 2) - 1)\n) / (\n  (ceiling((h + 1) * Dim(X, 2) / H_out) - floor(h * Dim(X, 2) / H_out)) * (ceiling((w + 1) * Dim(X, 3) / W_out) - floor(w * Dim(X, 3) / W_out))\n)\n",
    "param_map": {
      "output_size": [
        "H_out",
        "W_out"
      ]
    },
    "output_shape": [
      "Dim(X, 0)",
      "Dim(X, 1)",
      "H_out",
      "W_out"
    ],
    "mechanisms": [
      {
        "description": "Valid Output Size",
        "check": "(H_out > 0) & (W_out > 0)"
      }
    ]
  },
  "paddle": {
    "description": "Adaptive 2D average pooling over NCHW layout.",
    "definition_type": "operator",
    "math_symbol": "Y[n, c, i, j] == Sum(\n  X[n, c, h, w],\n  (h, floor(i * Dim(X, 2) / H_out), ceiling((i + 1) * Dim(X, 2) / H_out) - 1),\n  (w, floor(j * Dim(X, 3) / W_out), ceiling((j + 1) * Dim(X, 3) / W_out) - 1)\n) / (\n  (ceiling((i + 1) * Dim(X, 2) / H_out) - floor(i * Dim(X, 2) / H_out)) *\n  (ceiling((j + 1) * Dim(X, 3) / W_out) - floor(j * Dim(X, 3) / W_out))\n)\n",
    "param_map": {
      "output_size": [
        "H_out",
        "W_out"
      ]
    },
    "output_shape": [
      "Dim(X, 0)",
      "Dim(X, 1)",
      "H_out",
      "W_out"
    ],
    "mechanisms": [
      {
        "description": "Output Dimension Constraint",
        "check": "And(Eq(Dim(Y, 2), H_out), Eq(Dim(Y, 3), W_out))"
      },
      {
        "description": "Valid Output Size",
        "check": "And(Gt(H_out, 0), Gt(W_out, 0))"
      }
    ]
  }
}

{
  "pytorch": {
    "description": "Applies a 3D adaptive average pooling.",
    "definition_type": "operator",
    "math_symbol": "Sum(\n  Sum(\n    Sum(\n      Piecewise(\n        (X[n, c, kd, kh, kw],\n         (kd >= floor(d * Dim(X, 2) / D_out)) & \n         (kd < ceiling((d + 1) * Dim(X, 2) / D_out)) &\n         (kh >= floor(h * Dim(X, 3) / H_out)) & \n         (kh < ceiling((h + 1) * Dim(X, 3) / H_out)) &\n         (kw >= floor(w * Dim(X, 4) / W_out)) & \n         (kw < ceiling((w + 1) * Dim(X, 4) / W_out))),\n        (0, True)\n      ),\n      (kw, 0, Dim(X, 4) - 1)\n    ),\n    (kh, 0, Dim(X, 3) - 1)\n  ),\n  (kd, 0, Dim(X, 2) - 1)\n) / (\n  (ceiling((d + 1) * Dim(X, 2) / D_out) - floor(d * Dim(X, 2) / D_out)) *\n  (ceiling((h + 1) * Dim(X, 3) / H_out) - floor(h * Dim(X, 3) / H_out)) *\n  (ceiling((w + 1) * Dim(X, 4) / W_out) - floor(w * Dim(X, 4) / W_out))\n)\n",
    "param_map": {
      "output_size": [
        "D_out",
        "H_out",
        "W_out"
      ]
    },
    "output_shape": [
      "Dim(X, 0)",
      "Dim(X, 1)",
      "D_out",
      "H_out",
      "W_out"
    ],
    "mechanisms": [
      {
        "description": "Valid Output Size",
        "check": "(D_out > 0) & (H_out > 0) & (W_out > 0)"
      }
    ]
  },
  "paddle": {
    "description": "Adaptive 3D average pooling over NCDHW layout.",
    "definition_type": "operator",
    "math_symbol": "Y[n, c, i, j, k] == Sum(\n  X[n, c, d, h, w],\n  (d, floor(i * Dim(X, 2) / D_out), ceiling((i + 1) * Dim(X, 2) / D_out) - 1),\n  (h, floor(j * Dim(X, 3) / H_out), ceiling((j + 1) * Dim(X, 3) / H_out) - 1),\n  (w, floor(k * Dim(X, 4) / W_out), ceiling((k + 1) * Dim(X, 4) / W_out) - 1)\n) / (\n  (ceiling((i + 1) * Dim(X, 2) / D_out) - floor(i * Dim(X, 2) / D_out)) *\n  (ceiling((j + 1) * Dim(X, 3) / H_out) - floor(j * Dim(X, 3) / H_out)) *\n  (ceiling((k + 1) * Dim(X, 4) / W_out) - floor(k * Dim(X, 4) / W_out))\n)\n",
    "param_map": {
      "output_size": [
        "D_out",
        "H_out",
        "W_out"
      ]
    },
    "output_shape": [
      "Dim(X, 0)",
      "Dim(X, 1)",
      "D_out",
      "H_out",
      "W_out"
    ],
    "mechanisms": [
      {
        "description": "Output Dimension Constraint",
        "check": "And(Eq(Dim(Y, 2), D_out), Eq(Dim(Y, 3), H_out), Eq(Dim(Y, 4), W_out))"
      },
      {
        "description": "Valid Output Size",
        "check": "And(Gt(D_out, 0), Gt(H_out, 0), Gt(W_out, 0))"
      }
    ]
  }
}

{
