    "description": "Applies a 1D adaptive max pooling (Optimized Local Window).",
    "definition_type": "operator",
    "derived_variables": {
      "L_in": "Dim(X, 2)",
      "win_max": "ceiling(Dim(X, 2) / W_out)"
    },
    "math_symbol": "Max(\n  Piecewise(\n    (X[n, c, floor(w * L_in / W_out) + k], \n     (floor(w * L_in / W_out) + k < ceiling((w + 1) * L_in / W_out)) & \n     (floor(w * L_in / W_out) + k < L_in)),\n    (neg_infinity, True)\n  ),\n  (k, 0, win_max)\n)\n",
    "param_map": {
      "output_size": "W_out",
      "return_indices": "return_indices"
    },
    "output_shape": [
      "Dim(X, 0)",
      "Dim(X, 1)",
      "W_out"
    ],
    "mechanisms": [
      {
        "description": "Valid Output Size",
        "check": "W_out > 0"
      }
    ]
  },
  "paddle": {
    "description": "Adaptive 1D max pooling over NCW layout.",
    "definition_type": "operator",
    "math_symbol": "Max(\n  Piecewise(\n    (X[n, c, k], \n     (k >= floor(i * Dim(X, 2) / L_out)) & \n     (k < ceiling((i + 1) * Dim(X, 2) / L_out))),\n    (-1.0e+10, True)\n  ),\n  (k, 0, Dim(X, 2) - 1)\n)\n",
    "param_map": {
      "output_size": "L_out"
