target_definition.math_symbol:
Sum(
  Piecewise(
    (X[n, c, i * Strd + m - pad_val], (i * Strd + m - pad_val >= 0) & (i * Strd + m - pad_val < Dim(X, 2))),
    (0, True)
  ),
  (m, 0, K - 1)
) / Piecewise(
  (
    Sum(
      Piecewise(
        (1, (i * Strd + m - pad_val >= 0) & (i * Strd + m - pad_val < Dim(X, 2))),
        (0, True)
      ),
      (m, 0, K - 1)
    ), 
    exclusive
  ),
  (
    Min(K, Dim(X, 2) + 2*pad_val - i*Strd),
    True
  )
)

