{
  "pytorch": {
    "description": "1D Average Pooling. Divisor logic strictly handles ceil_mode out-of-bounds.",
    "definition_type": "operator",
    "math_symbol": "Sum(\n  Piecewise(\n    (X[n, c, Strd * w + m - P], (Strd * w + m - P >= 0) & (Strd * w + m - P < Dim(X, 2))),\n    (0, True)\n  ),\n  (m, 0, K - 1)\n) / Max(\n  Sum(\n    Piecewise(\n      (1, (Strd * w + m - P >= 0) & (Strd * w + m - P < Dim(X, 2))),\n      (Piecewise((1, count_include_pad), (0, True)), (Strd * w + m - P >= -P) & (Strd * w + m - P < Dim(X, 2) + P)),\n      (0, True)\n    ),\n    (m, 0, K - 1)\n  ),\n  1\n)\n",
    "param_map": {
      "kernel_size": "K",
      "stride": "Strd",
      "padding": "P",
      "ceil_mode": "ceil_mode",
      "count_include_pad": "count_include_pad"
    },
    "output_shape": [
      "Dim(X, 0)",
      "Dim(X, 1)",
      "Piecewise( (ceiling((Dim(X, 2) + 2 * P - K) / Strd + 1), ceil_mode), (floor((Dim(X, 2) + 2 * P - K) / Strd + 1), True) )"
    ],
    "mechanisms": [
      {
        "description": "Padding Constraint",
        "check": "P <= K / 2"
      },
      {
        "description": "Stride Positive",
        "check": "Strd > 0"
      }
    ]
  },
  "paddle": {
    "description": "Paddle 1D Average Pooling.",
    "definition_type": "operator",
    "math_symbol": "Sum(\n  Piecewise(\n    (X[n, c, i * Strd + m - pad_val], (i * Strd + m - pad_val >= 0) & (i * Strd + m - pad_val < Dim(X, 2))),\n    (0, True)\n  ),\n  (m, 0, K - 1)\n) / Piecewise(\n  (\n    Sum(\n      Piecewise(\n        (1, (i * Strd + m - pad_val >= 0) & (i * Strd + m - pad_val < Dim(X, 2))),\n        (0, True)\n      ),\n      (m, 0, K - 1)\n    ), \n    exclusive\n  ),\n  (\n    Min(K, Dim(X, 2) + 2*pad_val - i*Strd),\n    True\n  )\n)\n",
    "output_shape": [
      "n",
      "c",
      "Piecewise((ceiling((Dim(X, 2) + 2*pad_val - K) / Strd) + 1, ceil_mode), (floor((Dim(X, 2) + 2*pad_val - K) / Strd) + 1, True))"
    ],
    "param_map": {
      "kernel_size": [
        "K"
      ],
      "stride": [
        "Strd"
      ],
      "padding": [
        "pad_val"
      ],
      "exclusive": "exclusive",
      "ceil_mode": "ceil_mode"
    },
    "mechanisms": [
      {
        "description": "Input Rank Check",
        "check": "Rank(X) == 3"
      }
    ]
  }
}

source_definition.math_symbol:
Sum(
  Sum(
    (
      X[n, c, 
        Max(0, Min(S_h * i + kh - P_h, Dim(X, 2) - 1)), 
        Max(0, Min(S_w * j + kw - P_w, Dim(X, 3) - 1))
      ] * Piecewise(
        (1, (S_h * i + kh - P_h >= 0) & (S_h * i + kh - P_h < Dim(X, 2)) &
            (S_w * j + kw - P_w >= 0) & (S_w * j + kw - P_w < Dim(X, 3))),
        (0, True)
      )
    ),
    (kw, 0, K_w - 1)
  ),
  (kh, 0, K_h - 1)
) / Piecewise(
  (safe_div, safe_div > 0),
  (
    Piecewise(
      (K_h * K_w, count_include_pad & Not(ceil_mode)),
      (
        (Min(S_h * i - P_h + K_h, Dim(X, 2)) - Max(S_h * i - P_h, 0)) * (Min(S_w * j - P_w + K_w, Dim(X, 3)) - Max(S_w * j - P_w, 0)),
        True
      )
    ),
    True
  )
)

