    "math_symbol": "Sum(\n  (\n    Sum(\n      Piecewise(\n        (\n          Sum(\n            (\n              Exp(\n                Sum(\n                  (Sum(Piecewise((Query[n, l, k_q], batch_first == True), (Query[l, n, k_q], True)) * W_q[h * d_k + i_head, k_q], (k_q, 0, E_q - 1)) + Piecewise((B_q[h * d_k + i_head], bias == True), (0, True))) * Piecewise(\n                    (Sum(Piecewise((Key[n, s, k_k], batch_first == True), (Key[s, n, k_k], True)) * W_k[h * d_k + i_head, k_k], (k_k, 0, E_k - 1)) + Piecewise((B_k[h * d_k + i_head], bias == True), (0, True)), s < S_kv),\n                    (Bias_k_seq[0, 0, h * d_k + i_head], (add_bias_kv == True) & Eq(s, S_kv)),\n                    (0, True)\n                  ),\n                  (i_head, 0, d_k - 1)\n                ) * (1 / Sqrt(d_k))\n              ) / \n              Sum(\n                Exp(\n                  Sum(\n                    (Sum(Piecewise((Query[n, l, k_q], batch_first == True), (Query[l, n, k_q], True)) * W_q[h * d_k + i_head, k_q], (k_q, 0, E_q - 1)) + Piecewise((B_q[h * d_k + i_head], bias == True), (0, True))) * Piecewise(\n                      (Sum(Piecewise((Key[n, ss, k_k], batch_first == True), (Key[ss, n, k_k], True)) * W_k[h * d_k + i_head, k_k], (k_k, 0, E_k - 1)) + Piecewise((B_k[h * d_k + i_head], bias == True), (0, True)), ss < S_kv),\n                      (Bias_k_seq[0, 0, h * d_k + i_head], (add_bias_kv == True) & Eq(ss, S_kv)),\n                      (0, True)\n                    ),\n                    (i_head, 0, d_k - 1)\n                  ) * (1 / Sqrt(d_k))\n                ),\n                (ss, 0, S_kv_ext - 1)\n              )\n            ) * Piecewise(\n              (Sum(Piecewise((Value[n, s, k_v], batch_first == True), (Value[s, n, k_v], True)) * W_v[h * d_k + Mod(i_out, d_k), k_v], (k_v, 0, E_v - 1)) + Piecewise((B_v[h * d_k + Mod(i_out, d_k)], bias == True), (0, True)), s < S_kv),\n              (Bias_v_seq[0, 0, h * d_k + Mod(i_out, d_k)], (add_bias_kv == True) & Eq(s, S_kv)),\n              (0, True)\n            ),\n            (s, 0, S_kv_ext - 1)\n          ),\n          Eq(h, floor(i_out / d_k))\n        ),\n        (0, True)\n      ) * W_out[out, i_out],\n      (i_out, 0, d_model - 1)\n    )\n  ) + Piecewise((B_out[out], bias == True), (0, True)),\n  (h, 0, H - 1)\n)\n",
    "output_shape": [
      "Dim(Query, 0)",
      "Dim(Query, 1)",
      "d_model"
