{
  "pytorch": {
    "description": "PyTorch Unflatten Operator. Inverse of Flatten. Maps 1D index back to multi-dim coordinates.",
    "math_symbol": "Piecewise(\n  (\n    X[n, c * S_C4 + h * d2 + w],\n    (Rank(X) == 2) & (dim == 1) & (len(sizes) == 3)\n  ),\n  (\n    X[n, c * S_C3 + h],\n    (Rank(X) == 2) & (dim == 1) & (len(sizes) == 2)\n  )\n)\n",
    "derived_variables": {
      "d0": "Dim(sizes, 0)",
      "d1": "Dim(sizes, 1)",
      "d2": "Dim(sizes, 2)",
      "S_C4": "d1 * d2",
      "S_C3": "d1"
    },
    "output_shape": [
      "Piecewise( ((n, Dim(sizes, 0), Dim(sizes, 1), Dim(sizes, 2)), (Rank(X) == 2) & (Rank(sizes) == 3)), ((n, Dim(sizes, 0), Dim(sizes, 1)), (Rank(X) == 2) & (Rank(sizes) == 2)) )"
    ],
    "param_map": {
      "dim": "dim",
      "unflattened_size": "sizes"
    },
    "mechanisms": [
      {
        "description": "Unflatten Total Size Match",
        "check": "Dim(X, dim) == Piecewise((Dim(sizes, 0)*Dim(sizes, 1)*Dim(sizes, 2), Rank(sizes) == 3), (Dim(sizes, 0)*Dim(sizes, 1), Rank(sizes) == 2), (0, True))"
      }
    ]
  },
  "paddle": {
    "description": "Paddle Unflatten: Restore batch dim explicitly in output shape.",
    "definition_type": "operator",
    "math_symbol": "Piecewise(\n  (\n    Eq(Y[n, c, h, w], X[n, c * GetItem(p_shape, 1) * GetItem(p_shape, 2) + h * GetItem(p_shape, 2) + w]), \n    (len(p_shape) == 3) & Eq(axis, 1)\n  ),\n  (\n    Eq(Y[n, h, w], X[n, h * GetItem(p_shape, 1) + w]), \n    (len(p_shape) == 2) & Eq(axis, 1)\n  ),\n  (Eq(Y[n, i], X[n, i]), True)\n)\n",
    "output_shape": [
      "Piecewise(\n  ((Dim(X, 0), GetItem(p_shape, 0), GetItem(p_shape, 1), GetItem(p_shape, 2)), len(p_shape) == 3),\n  ((Dim(X, 0), GetItem(p_shape, 0), GetItem(p_shape, 1)), len(p_shape) == 2),\n  (p_shape, True)\n)\n"
    ],
    "param_map": {
      "axis": "axis",
      "p_shape": "shape"
    },
    "mechanisms": [
      {
        "description": "Rank Guard",
        "check": "Rank(X) >= 1"
      }
    ]
  }
}

{
  "pytorch": {
    "description": "PyTorch Unfold (Im2Col). Maps input patches to flattened columns.",
    "definition_type": "operator",
    "math_symbol": "Piecewise(\n  (\n    X[n, \n      c // (K_h * K_w), \n      (l // ((Dim(X, 3) + 2*P_w - D_w*(K_w-1) - 1) // S_w + 1)) * S_h \n      + ((c % (K_h * K_w)) // K_w) * D_h \n      - P_h,\n      (l % ((Dim(X, 3) + 2*P_w - D_w*(K_w-1) - 1) // S_w + 1)) * S_w \n      + ((c % (K_h * K_w)) % K_w) * D_w \n      - P_w\n    ],\n    ((l // ((Dim(X, 3) + 2*P_w - D_w*(K_w-1) - 1) // S_w + 1)) * S_h + ((c % (K_h * K_w)) // K_w) * D_h - P_h >= 0) &\n    ((l // ((Dim(X, 3) + 2*P_w - D_w*(K_w-1) - 1) // S_w + 1)) * S_h + ((c % (K_h * K_w)) // K_w) * D_h - P_h < Dim(X, 2)) &\n    ((l % ((Dim(X, 3) + 2*P_w - D_w*(K_w-1) - 1) // S_w + 1)) * S_w + ((c % (K_h * K_w)) % K_w) * D_w - P_w >= 0) &\n    ((l % ((Dim(X, 3) + 2*P_w - D_w*(K_w-1) - 1) // S_w + 1)) * S_w + ((c % (K_h * K_w)) % K_w) * D_w - P_w < Dim(X, 3))\n  ),\n  (0, True) \n)\n",
    "output_shape": [
      "Dim(X, 0)",
      "Dim(X, 1) * K_h * K_w",
      "((Dim(X, 2) + 2*P_h - D_h*(K_h-1) - 1) // S_h + 1) * ((Dim(X, 3) + 2*P_w - D_w*(K_w-1) - 1) // S_w + 1)"
    ],
    "param_map": {
      "kernel_size": [
        "K_h",
        "K_w"
      ],
      "dilation": [
        "D_h",
        "D_w"
      ],
      "padding": [
        "P_h",
        "P_w"
      ],
      "stride": [
        "S_h",
        "S_w"
      ]
    },
    "mechanisms": [
      {
        "description": "Input Rank Check",
        "check": "Rank(X) == 4"
      }
    ]
  },
  "paddle": null
}

